// BenchmarkTimerSuite measures each callable of the suite of Timer on
// timerIdle.
func BenchmarkTimerSuite(b *testing.B) {
	b.Run("C", func(b *testing.B) {
		clocktest.BenchTimerSuite(b, clocktest.TimerChecks.C.Callable, timerIdle)
	})
	b.Run("Reset", func(b *testing.B) {
		clocktest.BenchTimerSuite(b, clocktest.TimerChecks.Reset.Callable, timerIdle)
	})
	b.Run("Stop", func(b *testing.B) {
		clocktest.BenchTimerSuite(b, clocktest.TimerChecks.Stop.Callable, timerIdle)
	})
}

